messages.content:
Pull request: Update github.com/golang-jwt/jwt/v4 to v5.3.1

What was failing:
go build ./... failed:
# github.com/aalvaropc/upkeep-sample/auth
auth/token.go:24:6: undefined: jwt.StandardClaims
auth/token.go:29:57: c.ExpiresAt undefined (type Claims has no field or method ExpiresAt)
auth/token.go:57:23: undefined: jwt.StandardClaims
auth/token.go:80:13: claims.VerifyExpiresAt undefined (type Claims has no field or method VerifyExpiresAt)
auth/token.go:83:13: claims.VerifyIssuer undefined (type Claims has no field or method VerifyIssuer)
auth/token.go:83:50: claims.Subject undefined (type Claims has no field or method Subject)

The change:
```diff
diff --git a/auth/token.go b/auth/token.go
index efb974a..579de60 100644
--- a/auth/token.go
+++ b/auth/token.go
@@ -21,12 +21,17 @@ var (

 type Claims struct {
 	Scope string `json:"scope,omitempty"`
-	jwt.StandardClaims
+	jwt.RegisteredClaims
 }

 func (c Claims) Scopes() []string { return strings.Fields(c.Scope) }

-func (c Claims) Expiry() time.Time { return time.Unix(c.ExpiresAt, 0).UTC() }
+func (c Claims) Expiry() time.Time {
+	if c.ExpiresAt == nil {
+		return time.Time{}
+	}
+	return time.Unix(c.ExpiresAt.Unix(), 0).UTC()
+}

 func (c Claims) HasScope(scope string) bool { return slices.Contains(c.Scopes(), scope) }

@@ -54,11 +59,11 @@ func (i *Issuer) Issue(subject string, scopes ...string) (string, error) {
 	now := i.clock.Now()
 	claims := Claims{
 		Scope: strings.Join(scopes, " "),
-		StandardClaims: jwt.StandardClaims{
+		RegisteredClaims: jwt.RegisteredClaims{
 			Subject:   subject,
 			Issuer:    i.name,
-			IssuedAt:  now.Unix(),
-			ExpiresAt: now.Add(i.ttl).Unix(),
+			IssuedAt:  jwt.NewNumericDate(now),
+			ExpiresAt: jwt.NewNumericDate(now.Add(i.ttl)),
 		},
 	}
 	return jwt.NewWithClaims(jwt.SigningMethodHS256, claims).SignedString(i.key)
@@ -77,10 +82,10 @@ func (i *Issuer) Parse(token string) (Claims, error) {
 		return Claims{}, ErrInvalidToken
 	}
 	now := i.clock.Now().Unix()
-	if !claims.VerifyExpiresAt(now, true) {
+	if claims.ExpiresAt == nil || claims.ExpiresAt.Unix() < now {
 		return Claims{}, ErrExpired
 	}
-	if !claims.VerifyIssuer(i.name, true) || claims.Subject == "" {
+	if claims.Issuer != i.name || claims.Subject == "" {
 		return Claims{}, ErrInvalidToken
 	}
 	return claims, nil
```
